import fs from 'node:fs';
import readline from 'node:readline';
const [generation,root]=process.argv.slice(2);
const alive=pid=>{try{process.kill(pid,0);return true}catch(e){if(e.code==='ESRCH')return false;throw e}};
const record=method=>fs.appendFileSync(root+'/events.jsonl',JSON.stringify({generation,method,pid:process.pid,identity:'SDK-MCP-INSTANCE-'+generation})+'\n');
fs.writeFileSync(root+'/'+generation+'.json',JSON.stringify({pid:process.pid,identity:'SDK-MCP-INSTANCE-'+generation}));
record('spawn');
const keep=setInterval(()=>{},10000);
process.on('SIGTERM',()=>process.exit(0));
const send=(id,result)=>process.stdout.write(JSON.stringify({jsonrpc:'2.0',id,result})+'\n');
readline.createInterface({input:process.stdin}).on('line',line=>{
 let r;try{r=JSON.parse(line)}catch{return}
 if(r.id===undefined)return;
 record(r.method);
 if(r.method==='initialize')send(r.id,{protocolVersion:r.params.protocolVersion,capabilities:{tools:{}},serverInfo:{name:'sdk-directory-owned',version:'1.0.0'}});
 else if(r.method==='tools/list')send(r.id,{tools:[{name:'probe',description:'SDK directory owned lifecycle witness',inputSchema:{type:'object',properties:{},additionalProperties:false}}]});
 else if(r.method==='tools/call'){
  const prior=generation==='B'?JSON.parse(fs.readFileSync(root+'/A.json')):null;
  if(prior&&prior.identity!=='SDK-MCP-INSTANCE-A')throw Error('Invalid prior identity');
  const old=prior?alive(prior.pid):null;
  send(r.id,{content:[{type:'text',text:JSON.stringify({marker:'SDK-MCP-CALL-'+generation,previousAlive:old})}]});
 }else send(r.id,{});
});
// Deliberately keep the instance alive on EOF. The fixed SDK's close escalates
// to SIGTERM, awaiting child close before replacement. No timing-based assertion.

