import fs from 'node:fs';
const root=process.argv[2];
const alive=pid=>{try{process.kill(pid,0);return true}catch(e){if(e.code==='ESRCH')return false;throw e}};
for(const generation of ['A','B'])if(JSON.parse(fs.readFileSync(root+'/'+generation+'.json')).identity!=='SDK-MCP-INSTANCE-'+generation)throw Error('Invalid instance identity');
const result={marker:'SDK-MCP-CLEAR-PROBE',aAlive:alive(JSON.parse(fs.readFileSync(root+'/A.json')).pid),bAlive:alive(JSON.parse(fs.readFileSync(root+'/B.json')).pid)};
console.log(JSON.stringify(result));
if(result.aAlive||result.bAlive)process.exitCode=9;
